/**
 * Editable wording for system emails.
 *
 * Each email declares "slots" (subject, heading, paragraphs, button text...)
 * whose defaults are exactly the wording that shipped. John can override any
 * slot from the System emails page; the email's data parts (amount tables,
 * links, item lists) stay generated by code, so editing words can never
 * break a number.
 *
 * Slots can contain fill-ins in braces, e.g. "Hi {first_name},". Unknown
 * fill-ins are left as typed so a typo is visible in the preview rather than
 * silently disappearing.
 *
 * Pure: no server-only, no env. Used by the email builders, the live
 * preview in the browser, and the senders.
 */

export type CopySlot = {
  key: string;
  label: string;
  default: string;
  /** Multi-line: blank lines split it into separate paragraphs. */
  multiline?: boolean;
  help?: string;
};

export type EmailCopy = Record<string, string>;
export type CopyVars = Record<string, string | number | null | undefined>;

/** Defaults with any saved overrides on top. Empty overrides fall back to the default. */
export function resolveCopy(slots: CopySlot[], overrides?: Partial<EmailCopy> | null): EmailCopy {
  const out: EmailCopy = {};
  for (const s of slots) {
    const o = overrides?.[s.key];
    out[s.key] = typeof o === "string" && o.trim() ? o : s.default;
  }
  return out;
}

/** Replaces {name} fill-ins. Missing values become empty; unknown names stay visible. */
export function fill(template: string, vars: CopyVars): string {
  return template.replace(/\{([a-z_][a-z0-9_]*)\}/gi, (m, name: string) => {
    if (!(name in vars)) return m;
    const v = vars[name];
    return v === null || v === undefined ? "" : String(v);
  });
}

/** A multi-line slot as separate paragraphs (split on blank lines). */
export function paragraphsOf(text: string): string[] {
  return text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean);
}

/** Lines of a list slot (one item per line). */
export function linesOf(text: string): string[] {
  return text.split("\n").map((l) => l.trim()).filter(Boolean);
}

/** Every fill-in a piece of copy uses, for the editor's "unknown fill-in" warning. */
export function fillInsUsed(text: string): string[] {
  return [...new Set([...text.matchAll(/\{([a-z_][a-z0-9_]*)\}/gi)].map((m) => m[1]))];
}
